                    simpleExplanation = "👨‍🏫 توضیح و یاد دادن به زبان خودمانی (بفهمیم یعنی چی، نه اینکه فقط حفظ کنیم!):\n• پیش‌نیاز این درس: درس ۱۰ (پایه‌های استوار) را خوانده‌ایم؛ آنجا هشت معیار تمدن اسلامی را یاد گرفتیم: توحید، معاد، ولایت الهی، عدالت‌خواهی، تحکیم بنیان خانواده، دوستی با حق و دشمنی با باطل، اعتدال‌گرایی، تفکر و تعقل. حالا در این درس می‌خواهیم ببینیم نیاکان ما برای تحقق این معیارها چقدر تلاش کرده‌اند و تا چه اندازه موفق شده‌اند و از این تلاش چه درس‌هایی برای امروز خود می‌توانیم بگیریم؟ به ترکی می‌گوییم «شکوفایی، چیچک‌لنمک‌دیر» (شکوفایی، شکفتن است) و «جاهلیت، جاهیلیک‌دیر» (جاهلیت، نادانی است).\n• به زبان خیلی ساده، «عصر شکوفایی» یعنی دوره‌ای که تمدن اسلامی شکوفا شد و به اوج رسید؛ اما برای اینکه بفهمیم مسلمانان از چه نقطه‌ای حرکت کرده و به چه نقطه‌ای رسیده‌اند، اول باید نگاهی به اوضاع قبل از اسلام بیندازیم و آن را چراغ راه آینده قرار دهیم.\n• اوضاع اجتماعی و فرهنگی پیش از اسلام: امیرمؤمنان علی از آن ایام این گونه یاد می‌کند: «خداوند رسول خویش، محمد را زمانی فرستاد که مدتی از بعثت پیامبران پیشین می‌گذشت. ملت‌ها در خوابی عمیق فرورفته و فتنه و فساد، جهان را فراگرفته بود. رشته‌ها از هم گسیخته و آتش جنگ، زبانه می‌کشید» (نهج البلاغه، خطبه ۸۹). «مردم آن زمانه، مذاهب پراکنده و خواسته‌های متناقض و روش‌های متفاوت داشتند. برخی خدا را شبیه سایر مخلوقات می‌دانستند و برخی نیز غیر او را پرستش می‌کردند» (نهج البلاغه، خطبه ۱). «مردم از شیطان اطاعت می‌کردند و در راه او گام برمی‌داشتند. عَلَم‌های شیطان توسط این مردم به حرکت درآمده و پرچمش در فتنه‌هایی که شیطان، مردم را از طریق آن زیر پاهایش می‌کوفت و زیر سم‌هایش لگدمال می‌کرد، برافراشته شده بود» (نهج البلاغه، خطبه ۲). «شما مردم در آن زمان بدترین کیش و آیین را داشتید. در میان سنگ‌های سخت و مارهای زهرآلود زندگی می‌کردید، آب تیره می‌نوشیدید، غذای ناگوار می‌خوردید، خون یکدیگر را می‌ریختید و از خویشان می‌بریدید. بت‌ها در میان شما جای داشت و گناه، شما را فراگرفته بود» (نهج البلاغه، خطبه ۲۶).\n• بسیاری از مردم، داشتن دختر را ننگ می‌شمردند و وقتی به آنها خبر می‌دادند که خداوند دختری به آنها بخشیده، خشمگین می‌شدند (سوره نحل، آیه ۵۸). در داخل قبایل، غارت اموال، دزدی، برده‌داری، قمار، ربا و داد و ستدهای نادرست رواج داشت. کعبه مرکز بت‌های مختلف شده بود. بسیاری نیز به پرستش ارواح و ماه و ستارگان مشغول بودند.\n• خارج از شبه‌جزیره عربستان نیز، جهان آن روز آمیزه‌ای از تهی‌دستی، شلاق خوردن و سوختن محرومان، اندیشه‌های خشکیده و غرض‌آلود کشیشان و کاهنان و موبدان و تجمل‌پرستی درباریان بود. خسرو پرویز، پادشاه ایران در زمان طلوع اسلام خود را آدمی فناناپذیر از میان خدایان و خدایی بسیار جلیل در میان مردمان می‌شمرد (کریستن سن، ایرانیان در زمان ساسانیان، ترجمه رشید یاسمی، ص ۶۴۸). در پادشاهی ساسانی حدود یک درصد کل جمعیت آن روز ایران، همه چیز را در اختیار داشتند و بقیه مردم چون بردگان از حقوق اولیه و اساسی خویش محروم بودند (تاریخ اجتماعی ایران، مرتضی راوندی، ج ۲، صص ۱۰ و ۱۱). امپراتوری روم با استبداد اداره می‌شد و مسیحیت تحریف‌شده را، دستاویز حکومت خود قرار داده بود. تبعیض‌های نژادی، انحطاط اخلاقی و جنگ‌های پی‌درپی و طولانی‌مدت، این امپراتوری را به افول کشانده بود.\n• این گزارش اجمالی، سیمایی از شرایط فرهنگی و اجتماعی قبل از اسلام بود. رسول خدا آمد تا با همکاری و تلاش و همراهی مردم مقدمات تمدنی بر پایه معیارهای الهی و دینی را بنا کند. تمام رفتارهای پیامبر اکرم منطبق بر همین معیارها و معرفی آنها به جامعه و مردم بود. البته پیامبر اکرم واقعیت‌ها را می‌دانست و از میزان توانایی مردم و موانع پیش رو کاملاً آگاه بود. پیامبر می‌دانست جامعه که مجموعه‌ای از انسان‌های توانمند و ناتوان، موافق و مخالف و مؤمن و منافق است، تا چه میزان او را همراهی خواهد کرد. از همین جهت، همواره جامعه را نسبت به عظمت مسئولیت‌های بزرگشان آگاه می‌کرد و گاه با شدت به آنان هشدار می‌داد.\n• چطور توی ذهنمون قفلش کنیم؟ سه تصویر را قفل کن: «خواب عمیق» برای ملت‌ها پیش از اسلام، «یک درصد» برای ساسانیان (یک درصد همه چیز را داشتند)، «فقط هفده نفر» برای جاهلیت (فقط هفده نفر خواندن و نوشتن می‌دانستند — در درس ۱۰ آمد). حالا با این دید، نکات کامل و خط‌به‌خط زیر رو بخون تا ۱۰۰٪ ملکه ذهنت بشه:\n\n🎵 چهار کانال یادگیری این درس:\n• ترکی: «شکوفایی، چیچک‌لنمک‌دیر» — شکوفایی، شکفتن است؛ «جاهلیت، جاهیلیک‌دیر» — جاهلیت، نادانی است؛ «علم، بیلیک‌دیر» — علم، دانش است؛ «عدالت، عدالت‌دیر» — عدالت، عدالت است.\n• فارسی خیلی ساده: عصر شکوفایی یعنی دوره‌ای که تمدن اسلامی شکوفا شد؛ اما اول باید ببینیم پیش از اسلام، اوضاع چقدر بد بود تا بفهمیم مسلمانان چقدر راه آمده‌اند.\n• شکل: سه قاب را تصور کن: قاب اول «مکه پیش از اسلام» (بت‌ها، غارت، دزدی، قمار، ربا، دختر ننگ)، قاب دوم «ایران ساسانی» (خسرو پرویز، یک درصد همه چیز را داشتند)، قاب سوم «روم» (استبداد، مسیحیت تحریف‌شده، تبعیض نژادی).\n• ریتم سه‌ضربی: «جاهلیت! استبداد! تبعیض!»\n\n📖 آموزش کامل و پله‌به‌پله مفاهیم این گام:\n• سؤال درس: نیاکان ما برای تحقق معیارهای تمدن اسلامی چقدر تلاش کرده‌اند و تا چه اندازه موفق شده‌اند و از این تلاش چه درس‌هایی برای امروز خود می‌توانیم بگیریم؟\n• اوضاع پیش از اسلام (نهج البلاغه): خطبه ۸۹ (خواب عمیق ملت‌ها، فتنه و فساد، آتش جنگ)، خطبه ۱ (مذاهب پراکنده، خدا را شبیه مخلوقات می‌دانستند)، خطبه ۲ (اطاعت از شیطان، عَلَم‌های شیطان)، خطبه ۲۶ (بدترین کیش و آیین، سنگ‌های سخت و مارهای زهرآلود، آب تیره، غذای ناگوار، خون یکدیگر، بریدن از خویشان، بت‌ها).\n• مکه پیش از اسلام: داشتن دختر ننگ بود (نحل ۵۸)؛ غارت اموال، دزدی، برده‌داری، قمار، ربا، داد و ستدهای نادرست؛ کعبه مرکز بت‌ها؛ پرستش ارواح و ماه و ستارگان.\n• ایران ساسانی: خسرو پرویز خود را خدایی فناناپذیر می‌شمرد؛ حدود یک درصد جمعیت، همه چیز را در اختیار داشتند و بقیه چون بردگان محروم بودند.\n• امپراتوری روم: استبداد، مسیحیت تحریف‌شده، تبعیض‌های نژادی، انحطاط اخلاقی، جنگ‌های پی‌درپی و طولانی‌مدت.",
                    visualDiagramText = "┌── نقشه مفهومی: عصر شکوفایی یعنی چی؟ ──┐\n│ سؤال درس ⬅ نیاکان ما برای تحقق معیارهای تمدن اسلامی چقدر تلاش کرده‌اند و تا چه اندازه موفق شده‌اند و از این تلاش چه درس‌هایی برای امروز خود می‌توانیم بگیریم؟\n│ اوضاع پیش از اسلام (نهج البلاغه) ⬅ خطبه ۸۹ (خواب عمیق ملت‌ها، فتنه و فساد، آتش جنگ)؛ خطبه ۱ (مذاهب پراکنده)؛ خطبه ۲ (اطاعت از شیطان)؛ خطبه ۲۶ (بدترین کیش و آیین، سنگ‌های سخت و مارهای زهرآلود، آب تیره، غذای ناگوار، خون یکدیگر، بریدن از خویشان، بت‌ها)\n│ مکه پیش از اسلام ⬅ داشتن دختر ننگ بود (نحل ۵۸)؛ غارت اموال، دزدی، برده‌داری، قمار، ربا؛ کعبه مرکز بت‌ها؛ پرستش ارواح و ماه و ستارگان\n│ ایران ساسانی ⬅ خسرو پرویز خود را خدایی فناناپذیر می‌شمرد؛ حدود یک درصد جمعیت، همه چیز را در اختیار داشتند و بقیه چون بردگان محروم بودند\n│ امپراتوری روم ⬅ استبداد، مسیحیت تحریف‌شده، تبعیض‌های نژادی، انحطاط اخلاقی، جنگ‌های پی‌درپی و طولانی‌مدت\n└── نتیجه: رسول خدا آمد تا با همکاری مردم، مقدمات تمدنی بر پایه معیارهای الهی و دینی را بنا کند ──┘",
